              <div className="flex gap-2">
                <input
                  ref={arquivoRef}
                  type="file"
                  multiple
                  hidden
                  onChange={(e) => e.target.files?.length && executar("Lendo os arquivos enviados…", () => api.enviarArquivos(e.target.files!))}
                />
                <button
                  onClick={() => arquivoRef.current?.click()}
