import gzip,re,glob,collections
pats={k:re.compile(v) for k,v in {"anthropic":r"sk-ant-[A-Za-z0-9_-]{10,}","openai_proj":r"sk-proj-[A-Za-z0-9_-]{20,}","sk-":r"\bsk-[A-Za-z0-9]{20,}","github":r"ghp_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,}","aws":r"AKIA[0-9A-Z]{16}","slack":r"xox[bpas]-[A-Za-z0-9-]{10,}","privkey":r"BEGIN [A-Z ]*PRIVATE KEY","openai_env":r"OPENAI_API_KEY\s*=\s*[A-Za-z0-9_-]{12,}"}.items()}
img=re.compile(r'"data":"[A-Za-z0-9+/=]{200,}"')
em=re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[a-z]{2,}')
for f in sorted(glob.glob("PROMPTS/sessoes/andrespleite/*")):
    op=gzip.open if f.endswith(".gz") else open
    hits=collections.Counter(); emails=collections.Counter()
    for line in op(f,"rt",errors="replace"):
        spans=[(m.start(),m.end()) for m in img.finditer(line)]
        for k,p in pats.items():
            for m in p.finditer(line):
                if not any(a<=m.start()<b for a,b in spans): hits[k]+=1
        for m in em.finditer(line):
            e=m.group(); emails[re.sub(r'^(..)[^@]*@',r'\1***@',e)]+=1
    print(f.split("/")[-1][:14], "segredos:", dict(hits) or 0, "emails:", dict(emails.most_common(5)))
EOF

